//! Extraction tests: the Rust port reproduces the TypeScript extraction's documents,
//! diagnostics, imports and imported names byte for byte on the `surface` fixture.
//!
//! The expectation is `tests/fixtures/frozen/extract_parity.json`, the verbatim
//! output of the TypeScript extraction pass (`extractProject` from
//! `packages/core/dist`) captured before `packages/core/src` was deleted: the
//! resolved config, the discovered inputs with their text, and everything extraction
//! produced. The compiler under test is the Rust port; the frozen inputs are fed to
//! [`flamme_core::extract::extract_project`] exactly as the TypeScript inputs were.
//!
//! The fixture project is generated by
//! `crates/flamme-core/tests/fixtures/make_surface.mjs`; it covers the `.gql`
//! surface, both `.vue` script blocks (including a file whose plain block comes
//! first), a tag inside a `<template>` (never scanned), `<script src>`, TSX/JSX,
//! `graphql("…")`, template escapes and CRLF, astral characters, aliased and
//! namespace imports, `require('$flamme')`, `GraphQL<…>`, the page-module
//! convention and the SFC error shapes.

mod support;

use std::path::{Path, PathBuf};
use std::sync::OnceLock;

use flamme_core::config::RustConfig;
use flamme_core::diagnostics::Diagnostic;
use flamme_core::extract::{
    DocumentSurface, RawDocument, SourceFile, extract_project, resolve_page_module,
};
use support::{Frozen, diagnostic_keys, fixture, frozen};

/// Everything one frozen extraction run printed.
struct Extraction {
    config: RustConfig,
    inputs: Vec<SourceFile>,
    documents: Vec<serde_json::Value>,
    diagnostics: Vec<Diagnostic>,
    imports: Vec<serde_json::Value>,
    imported_names: Vec<String>,
}

/// Builds the extraction view of one frozen snapshot document.
fn extraction_from_json(project: &Path, value: &serde_json::Value) -> Extraction {
    let run = Frozen::from_json(project, value);
    Extraction {
        config: run.config,
        inputs: run.inputs,
        documents: value["documents"].as_array().cloned().unwrap_or_default(),
        diagnostics: run.diagnostics,
        imports: value["imports"].as_array().cloned().unwrap_or_default(),
        imported_names: serde_json::from_value(value["importedNames"].clone())
            .expect("importedNames deserialize"),
    }
}

/// The frozen document shape, from the Rust side.
fn document_facts(document: &RawDocument) -> serde_json::Value {
    serde_json::json!({
        "name": document.name,
        "kind": document.kind.as_str(),
        "raw": document.raw,
        "file": document.file,
        "relativePath": document.relative_path,
        "surface": match document.surface {
            DocumentSurface::File => "file",
            DocumentSurface::Tag => "tag",
            DocumentSurface::Script => "script",
            DocumentSurface::Module => "module",
            DocumentSurface::Composed => "composed",
        },
        "offset": document.offset,
        "start": document.start,
        "end": document.end,
        "sourceOffsets": document.source_offsets,
        "source": document.source.as_str(),
    })
}

const DOCUMENT_KEYS: [&str; 11] = [
    "name",
    "kind",
    "raw",
    "file",
    "relativePath",
    "surface",
    "offset",
    "start",
    "end",
    "sourceOffsets",
    "source",
];

/// Compares the frozen documents with the port's, field by field.
fn assert_documents(expected: &[serde_json::Value], actual: &[RawDocument]) {
    let actual: Vec<serde_json::Value> = actual.iter().map(document_facts).collect();
    assert_eq!(
        expected.len(),
        actual.len(),
        "document count differs\n  frozen: {:?}\n  rust:   {:?}",
        expected.iter().map(|document| &document["relativePath"]).collect::<Vec<_>>(),
        actual.iter().map(|document| &document["relativePath"]).collect::<Vec<_>>(),
    );
    for (index, (expected, actual)) in expected.iter().zip(actual.iter()).enumerate() {
        if expected == actual {
            continue;
        }
        for key in DOCUMENT_KEYS {
            if expected[key] != actual[key] {
                panic!(
                    "document {index} ({}) differs at `{key}`\n  frozen: {}\n  rust:   {}",
                    expected["relativePath"], expected[key], actual[key]
                );
            }
        }
    }
}

/// The frozen snapshot run, shared by every test in this binary.
fn snapshot() -> &'static Extraction {
    static SNAPSHOT: OnceLock<Extraction> = OnceLock::new();
    SNAPSHOT.get_or_init(|| {
        let snapshots = frozen("extract_parity");
        let surface = extraction_from_json(&fixture("surface"), &snapshots["surface"]);
        // A silent walk change (a fixture file that stops being discovered) would
        // weaken every comparison below.
        assert_eq!(surface.inputs.len(), 60, "the surface fixture discovers 60 files");
        surface
    })
}

/// One extraction run over the fixture plus its frozen snapshot.
fn surface() -> (&'static Extraction, flamme_core::extract::ExtractResult) {
    let snapshot = snapshot();
    let result = extract_project(&snapshot.config, &snapshot.inputs);
    (snapshot, result)
}

#[test]
fn surface_documents_match_the_frozen_expectation() {
    let (snapshot, result) = surface();
    assert_eq!(result.documents.len(), 34, "the surface fixture extracts 34 documents");
    assert_documents(&snapshot.documents, &result.documents);
}

#[test]
fn surface_diagnostics_match_the_frozen_expectation() {
    let (snapshot, result) = surface();
    assert_eq!(diagnostic_keys(&snapshot.diagnostics), diagnostic_keys(&result.diagnostics));
    assert_eq!(snapshot.diagnostics.len(), 36, "the surface fixture reports 36 diagnostics");
}

#[test]
fn surface_imports_and_imported_names_match_the_frozen_expectation() {
    let (snapshot, result) = surface();
    let expected: Vec<serde_json::Value> = snapshot.imports.clone();
    let actual: Vec<serde_json::Value> = result
        .imports
        .iter()
        .map(|entry| {
            serde_json::json!({
                "file": entry.file,
                "relativePath": entry.relative_path,
                "specifier": entry.specifier,
                "resolved": entry.resolved,
                "offset": entry.offset,
            })
        })
        .collect();
    assert_eq!(expected, actual, "gql imports differ");
    assert_eq!(snapshot.imported_names, result.imported_names, "imported names differ");
    assert_eq!(result.imported_names, vec!["graphql", "gql", "*", "flamme"]);
}

/// The `files` list mirrors the discovered inputs, and the routing helpers follow
/// the resolved configuration.
#[test]
fn files_and_routing_helpers_match_the_discovered_project() {
    use flamme_core::page_module::{page_module_role, routing_document_name, routing_pages_prefix};

    let (snapshot, result) = surface();
    assert_eq!(result.files.len(), snapshot.inputs.len());
    for (file, input) in result.files.iter().zip(snapshot.inputs.iter()) {
        assert_eq!(file.relative, input.relative);
        assert_eq!(file.absolute, input.absolute);
        assert_eq!(file.size, input.size);
        assert_eq!(file.mtime_ms, input.mtime_ms);
    }

    let mut config = snapshot.config.clone();
    assert_eq!(routing_pages_prefix(&config), "src/pages/");
    config.routing.pages_dir = "./app/pages/".into();
    assert_eq!(routing_pages_prefix(&config), "app/pages/");
    for rejected in ["", "/absolute", "../outside"] {
        config.routing.pages_dir = rejected.into();
        assert_eq!(routing_pages_prefix(&config), "src/pages/");
    }
    assert_eq!(routing_document_name(&config, "page"), "+page.gql");
    assert_eq!(routing_document_name(&config, "layout"), "+layout.gql");
    config.routing.document_file = "query.gql".into();
    config.routing.layout_document_file = "nested/layout.gql".into();
    assert_eq!(routing_document_name(&config, "page"), "query.gql");
    // A configured document file never carries a separator.
    assert_eq!(routing_document_name(&config, "layout"), "+layout.gql");
    assert_eq!(page_module_role("src/pages/x/+page.ts"), Some("page"));
    assert_eq!(page_module_role("src/pages/x/+layout.ts"), Some("layout"));
    assert_eq!(page_module_role("src/pages/x/+page.vue"), None);
}

