/// The `Page` resolution outcomes, one per fixture page module.
#[test]
fn page_modules_resolve_to_the_expected_documents() {
    let (_snapshot, result) = surface();
    let inputs: Vec<SourceFile> = snapshot().inputs.clone();
    let source_of = |relative: &str| -> &SourceFile {
        inputs.iter().find(|file| file.relative == relative).expect("the fixture file exists")
    };
    let document_name = |index: Option<usize>| -> Option<String> {
        index.and_then(|index| result.documents.get(index)).map(|document| document.name.clone())
    };
    let resolve = |relative: &str| -> (Option<String>, Option<String>) {
        let resolution =
            resolve_page_module(&snapshot().config, source_of(relative), &result.documents);
        (document_name(resolution.document), resolution.diagnostic.map(|entry| entry.code))
    };

    assert_eq!(resolve("src/pages/ok/+page.ts"), (Some("OkPage".into()), None));
    assert_eq!(resolve("src/pages/alias/+page.ts"), (Some("AliasPage".into()), None));
    assert_eq!(resolve("src/pages/wrapped/+page.ts"), (Some("WrappedPage".into()), None));
    assert_eq!(resolve("src/pages/imported/+page.ts"), (Some("SharedPage".into()), None));
    // The specifier has no extension: `specifierCandidates` probes `.ts` first.
    assert_eq!(resolve("src/pages/probed/+page.ts"), (Some("MoveDisplay".into()), None));
    // A `+page.ts` outside the pages directory is not a page module at all.
    assert_eq!(resolve("src/elsewhere/+page.ts"), (None, Some("FLM1028".into())));
    // The generated `<Name>Document` spelling resolves by document name.
    assert_eq!(resolve("src/pages/named/+page.ts"), (Some("Alpha".into()), None));
    assert_eq!(resolve("src/pages/missing/+page.ts"), (None, Some("FLM1028".into())));
    assert_eq!(resolve("src/pages/bad/+page.ts"), (None, Some("FLM1029".into())));
    assert_eq!(resolve("src/pages/typed/+page.ts"), (None, Some("FLM1029".into())));
    assert_eq!(resolve("src/pages/reexport/+page.ts"), (None, Some("FLM1029".into())));
    assert_eq!(resolve("src/pages/ambiguous/+page.ts"), (None, Some("FLM1029".into())));

    // A `<script src>` block is scanned as the target file, so its document is
    // attributed to the target and de-duplicated against the direct scan.
    let shared: Vec<&RawDocument> = result
        .documents
        .iter()
        .filter(|document| document.relative_path == "src/shared/script.ts")
        .collect();
    assert_eq!(shared.len(), 1);
    assert_eq!(shared[0].name, "MoveDisplay");
    assert_eq!(shared[0].surface, DocumentSurface::Script);
}

/// The PoC fixture (the seven documents of `research/pokedex-example-spec.md` C,
/// across `.gql`/`.ts`/`.vue`) extracts identically too.
#[test]
fn poc_documents_match_the_frozen_expectation() {
    let snapshots = frozen("extract_parity");
    let snapshot = extraction_from_json(&fixture("poc"), &snapshots["poc"]);
    let result = extract_project(&snapshot.config, &snapshot.inputs);
    assert_eq!(snapshot.documents.len(), 7);
    assert_documents(&snapshot.documents, &result.documents);
    assert_eq!(diagnostic_keys(&snapshot.diagnostics), diagnostic_keys(&result.diagnostics));
    assert!(result.diagnostics.is_empty());
    assert!(result.imports.is_empty());
    assert_eq!(result.imported_names, vec!["graphql", "MoveDisplay", "SpeciesPreview", "SpriteInfo"]);
    // Two queries from `.gql` files, one mutation from a `.ts` tag, four fragments
    // from the components' `<script setup>` blocks.
    let count = |kind: flamme_core::contract::ArtifactKind| {
        result.documents.iter().filter(|document| document.kind == kind).count()
    };
    assert_eq!(count(flamme_core::contract::ArtifactKind::Query), 2);
    assert_eq!(count(flamme_core::contract::ArtifactKind::Mutation), 1);
    assert_eq!(count(flamme_core::contract::ArtifactKind::Fragment), 4);
}

/// The offsets are UTF-16 code unit indices: escaped templates, CRLF and astral
/// characters must map back to the exact file positions.
#[test]
fn cooked_templates_and_offsets_match_the_frozen_expectation() {
    let (snapshot, result) = surface();
    let find = |relative: &str, name: &str| -> RawDocument {
        result
            .documents
            .iter()
            .find(|document| document.relative_path == relative && document.name == name)
            .unwrap_or_else(|| panic!("{relative} declares {name}"))
            .clone()
    };
    let fact = |relative: &str, name: &str| -> serde_json::Value {
        let expected = snapshot
            .documents
            .iter()
            .find(|document| {
                document["relativePath"] == relative && document["name"] == name
            })
            .unwrap_or_else(|| panic!("the snapshot has {relative}#{name}"));
        assert_eq!(document_facts(&find(relative, name)), *expected);
        expected.clone()
    };

    // Escape sequences: `\t` cooks to a tab, `\\` to a backslash, `` \` `` to a
    // backtick, `\u0041`/`\x42` to A/B and `\$` to a dollar; the line
    // continuations cook away.
    let escaped = fact("src/escapes.ts", "Escaped");
    assert!(escaped["raw"].as_str().expect("raw").contains("a\tb\\\\c`dAB$e"));
    let continued = fact("src/escapes.ts", "Continued");
    assert_eq!(continued["raw"], "query Continued { \tfavorites { id } }");

    // CRLF cooks to LF, and every produced character maps back to its file offset.
    let crlf = fact("src/crlf.ts", "Crlf");
    assert!(!crlf["raw"].as_str().expect("raw").contains('\r'));
    let offsets = crlf["sourceOffsets"].as_array().expect("offsets");
    assert_eq!(offsets.len(), crlf["raw"].as_str().expect("raw").encode_utf16().count() + 1);

    // An astral character is two UTF-16 code units, so it takes two offsets.
    let emoji = fact("src/emoji.ts", "Emoji");
    let raw = emoji["raw"].as_str().expect("raw");
    let offsets = emoji["sourceOffsets"].as_array().expect("offsets");
    assert_eq!(offsets.len(), raw.encode_utf16().count() + 1);
    assert_eq!(offset_span(&emoji), raw.encode_utf16().count() as u64);
}

/// `end - start` is the document's source span in UTF-16 units.
fn offset_span(document: &serde_json::Value) -> u64 {
    let start = document["start"].as_u64().expect("start");
    let end = document["end"].as_u64().expect("end");
    end - start
}

